const chapters=configs.map((x,i)=>{
 const c=source.chapters[i];
 return {id:c.id,pronunciation:{focus:x.p[0],explanation:x.p[1],examples:x.p.slice(2).map(a=>{const [text,zh]=a.split('|');return {text,zh}})},grammarNotes:x.g,cultureNote:x.c,vocabularyNotes:x.v.map(([j,note])=>({head:c.vocab[j].head,note})),transfer:x.t.map(([prompt,text,zh,explanation],j)=>({id:`${c.id}-transfer-${j+1}`,prompt,text,zh,explanation})),grammarCheck:x.b.map(([a,b,explanation],j)=>{const answer=(i+j)%3;const options=[a,b];options.splice(answer,0,c.lessons[j].text);return {prompt:`选择表达“${c.lessons[j].zh}”且语法、用法正确的一项。`,options,answer,explanation}}),writingChecklist:x.w,speakingFollowups:x.s};
});
const q=(prompt,options,answer,explanation)=>({prompt,options,answer,explanation});
const checkpoints=[
{id:'pt-stage-1',afterChapter:6,target:'A1',reading:{text:'A Joana trabalha numa pequena loja de fruta. Hoje chega às oito e abre a porta às oito e meia. Na primeira caixa há peras, e as maçãs estão junto à janela. Um cliente pede dois quilos de peras, mas leva apenas um quilo porque o saco é pequeno. Paga em dinheiro e pede o talão. Antes de sair, pergunta a que horas a loja fecha. A Joana responde: às seis da tarde.',questions:[q('商店几点开门？',['八点','八点半','下午六点'],1,'八点是到达时间；abre a porta às oito e meia 才是开门时间。'),q('苹果放在哪里？',['窗边','门外','第一只箱子里'],0,'as maçãs estão junto à janela；第一只箱子里是梨。'),q('顾客最终买了多少梨？',['两公斤','半公斤','一公斤'],2,'最初要求两公斤，但最后 leva apenas um quilo。'),q('顾客怎样付款？',['银行卡','现金','未付款'],1,'Paga em dinheiro 明确表示现金付款。')]},listening:{text:'Boa tarde. Queria encomendar pão para amanhã de manhã. Somos quatro pessoas e precisamos de seis pães pequenos. Não queremos queijo nem leite. Posso passar aqui às nove? O meu nome é Teresa. Se não perceber o nome, posso escrevê-lo neste papel. Queria saber também quanto custa a encomenda toda.',questions:[q('预订何时取用的面包？',['今天下午','明天早上','明晚'],1,'para amanhã de manhã 指明预订用途时间。'),q('需要几个小面包？',['四个','九个','六个'],2,'四是人数；seis pães pequenos 才是面包数量。'),q('顾客打算几点来？',['九点','六点','四点'],0,'Posso passar aqui às nove? 是询问能否九点来。'),q('没听清名字时顾客提出什么办法？',['改用邮箱','写在纸上','明天再说'],1,'posso escrevê-lo neste papel 指写在这张纸上。')]},writing:'给面包店写5–6句预订信息：说明明天取货的时间、两种食品及数量，询问总价，并在末尾礼貌感谢。不得使用真实联系方式。',speaking:'两人模拟首次到咖啡馆预订：顾客点两样食品、问价格；店员说明一种缺货；顾客选择替代品并确认取货时间。'},
{id:'pt-stage-2',afterChapter:12,target:'A2',reading:{text:'O Miguel vai passar duas noites numa pensão perto do rio. Quando chega, a rececionista explica que o quarto fica no primeiro andar e que não há elevador. O Miguel traz uma mala pesada e pede ajuda. Depois pergunta pelo pequeno-almoço, que começa às sete e termina às dez. Quer sair cedo para visitar um amigo, por isso combina tomar o pequeno-almoço às sete e meia. À noite, prefere jantar fora com esse amigo.',questions:[q('住宿离哪里近？',['河流','机场','学校'],0,'numa pensão perto do rio 指河边附近的旅馆。'),q('为什么需要帮忙？',['没有房间','行李重且没有电梯','早餐结束'],1,'文中先说明没有电梯，又说 mala pesada，因此请求帮助。'),q('早餐供应到几点？',['七点','七点半','十点'],2,'termina às dez；七点半是他打算吃早餐的时间。'),q('晚上他打算怎样用餐？',['在房间独自吃','与朋友外出吃','不吃晚餐'],1,'prefere jantar fora com esse amigo 明确计划。')]},listening:{text:'Olá, sou a tua vizinha do andar de cima. Amanhã vêm cá dois amigos e vamos cozinhar ao fim da tarde. Queria perguntar se precisas de usar a cozinha entre as seis e as sete. Se precisares, posso começar mais cedo. Também queria convidar-te para jantar connosco. Não há problema se não puderes ficar até ao fim.',questions:[q('说话人住在哪里？',['楼上','楼下','另一栋楼'],0,'a tua vizinha do andar de cima 表示楼上的女邻居。'),q('什么时候会有朋友来？',['今晚','明天','下周'],1,'Amanhã vêm cá dois amigos。'),q('她主要核实哪一时段的厨房使用？',['五点到六点','七点到八点','六点到七点'],2,'entre as seis e as sete 明确核实区间。'),q('对方不能待到最后时她的态度是什么？',['必须参加全程','没有关系','取消聚餐'],1,'Não há problema se não puderes ficar até ao fim。')]},writing:'写一条给室友的消息，说明明天有访客、需要厨房的时段，询问是否冲突；给出一个替代时段，并邀请室友参加。写6–8句。',speaking:'两人讨论周末访问朋友：提出交通方式和到达时间；对方临时有安排；共同改约时间，并说明住宿或餐饮的一个需求。'},
{id:'pt-stage-3',afterChapter:18,target:'B1',reading:{text:'A associação do bairro enviou um email sobre uma oficina de fotografia. A Rita quer participar, mas o horário coincide com uma reunião de trabalho. Antes de pagar a inscrição, escreve à organização para perguntar se haverá outra sessão. Recebe uma resposta que propõe sábado de manhã, num edifício diferente. A Rita pede a morada completa e confirma que pode levar a sua própria máquina. Só depois guarda a resposta e ajusta a agenda.',questions:[q('Rita 为什么还没有直接报名付款？',['不知道兴趣','与工作会议冲突','没有照相机'],1,'o horário coincide com uma reunião de trabalho；她先询问是否有另一个场次。'),q('主办方提出的新时段是什么？',['周六早上','周五晚上','周一下午'],0,'a resposta propõe sábado de manhã。'),q('除了时间外还发生什么变化？',['费用翻倍','老师更换','地点换了建筑'],2,'num edifício diferente 指不同建筑。'),q('调整日程前她进一步确认什么？',['朋友是否参加','完整地址及能否带自己的相机','是否可带宠物'],1,'pede a morada completa e confirma que pode levar a sua própria máquina。')]},listening:{text:'Bom dia. Estou a ligar por causa do ficheiro que enviou ontem. Consegui abrir o anexo, mas faltam os dados da última semana. Poderia enviar uma versão atualizada até às três? Não precisa de alterar o texto da apresentação. Se não conseguir reunir todos os números, envie primeiro os que já confirmou e indique o que falta.',questions:[q('来电的主要问题是什么？',['打不开附件','缺少上周数据','文字太长'],1,'说话人能打开附件，但 faltam os dados da última semana。'),q('希望何时前收到更新？',['两点','五点','三点'],2,'até às três 指三点前。'),q('演示文稿文字需要修改吗？',['不需要','全部重写','只改标题'],0,'Não precisa de alterar o texto da apresentação。'),q('暂时无法收齐数据时怎么办？',['不发任何内容','先发已核实数据并标出缺失部分','任意估算缺项'],1,'envie primeiro os que já confirmou e indique o que falta 给出明确备选动作。')]},writing:'写一封80–100词的工作邮件：说明附件缺少哪一部分资料，礼貌请求补充并给出期限；如无法按时完成，提出先发送已核实部分的方案，最后请求确认收到。',speaking:'两人模拟更改课程报名：学习者解释时间冲突，询问另一时段与费用；工作人员提出不完全合适的选择；双方核实细节并约定下一次联系。'},
{id:'pt-stage-4',afterChapter:24,target:'B1',reading:{text:'Na segunda-feira, o André recebeu duas mensagens sobre uma visita de estudo. Uma indicava a estação antiga; a outra, a praça do mercado. Como não sabia qual era a versão mais recente, contactou a organizadora pelo número habitual. Descobriu que o local tinha mudado, mas a hora continuava igual. Avisou os colegas e guardou a confirmação. No sábado, um amigo atrasou-se. O grupo esperou dez minutos e depois combinou encontrá-lo junto à entrada do museu.',questions:[q('两条消息哪里不同？',['集合地点','活动日期','人数'],0,'分别指 estação antiga 与 praça do mercado，即地点不同。'),q('André 如何核实？',['猜测较近地点','联系惯常号码上的组织者','询问陌生发件人'],1,'contactou a organizadora pelo número habitual。'),q('核实后得知什么？',['时间地点都变','活动取消','地点变了但时间未变'],2,'o local tinha mudado, mas a hora continuava igual。'),q('朋友迟到后大家最后怎样安排？',['取消参观','在博物馆入口与他会合','一直在原地等'],1,'等十分钟后 combinou encontrá-lo junto à entrada do museu。')]},listening:{text:'Olá a todos. Já falei com o senhorio sobre a janela da sala. Ele pediu fotografias antes de marcar a reparação. Posso enviá-las hoje, mas preciso de saber quando há alguém em casa na próxima semana. Se o técnico só puder vir de manhã, consigo ficar na terça-feira. Nos outros dias, seria bom combinarmos quem fica em casa. Depois envio ao grupo a confirmação por escrito.',questions:[q('房东安排维修前需要什么？',['照片','新的合同','购买收据'],0,'pediu fotografias antes de marcar a reparação。'),q('说话人何时能发照片？',['下周','今天','维修后'],1,'Posso enviá-las hoje。'),q('若技术人员只能上午来，说话人哪天能在家？',['周五','周一','周二'],2,'consigo ficar na terça-feira。'),q('确认安排后会如何通知大家？',['电话逐个通知','群内发送书面确认','贴在商店门口'],1,'envio ao grupo a confirmação por escrito。')]},writing:'写80–100词向合住者汇报一次维修安排：交代已经联系的人、对方要求、尚待确认的时间；给出至少一个条件方案，并说明会如何保存和转告最终答复。',speaking:'两人协商一天内的多项生活任务：一项预约改期、一项共用空间维修。轮流提出追问，区分已确认与未确认信息；在时间冲突时给出备选方案，最后口头归纳各自下一步。'}
];
const result={locale:'pt-PT',notice:'本材料为欧洲葡语教学支持，未经专业语言审定；阶段目标仅用于练习组织，不构成专业校准或等级保证。首次接触材料与熟题复测应分别记录；不构成医疗、法律、金融或公共服务办理建议。',chapters,checkpoints};
const original=new Set(source.chapters.flatMap(c=>c.lessons.map(l=>l.text.trim().toLocaleLowerCase('pt-PT'))));
const seen=new Set();let count=0;
for(const c of chapters){
 for(const [key,n] of Object.entries({grammarNotes:3,vocabularyNotes:3,transfer:6,grammarCheck:3,writingChecklist:3,speakingFollowups:3}))if(c[key].length!==n)throw Error(`${c.id} ${key}`);
 if(c.pronunciation.examples.length!==2)throw Error('pronunciation');
 for(const t of c.transfer){const k=t.text.trim().toLocaleLowerCase('pt-PT');if(original.has(k))throw Error('原课重复 '+t.id);if(seen.has(k))throw Error('新句重复 '+t.id);seen.add(k);count++;}
 for(const q of c.grammarCheck)if(q.options.length!==3||!Number.isInteger(q.answer)||q.answer<0||q.answer>2)throw Error('选项结构');
 const base=source.chapters.find(x=>x.id===c.id);for(const v of c.vocabularyNotes)if(!base.vocab.some(x=>x.head===v.head))throw Error('词表外词头');
}
const passages=new Set();const passageCounts=[];
for(const [i,c] of checkpoints.entries()){
 if(c.afterChapter!==[6,12,18,24][i]||c.target!==['A1','A2','B1','B1'][i])throw Error('阶段映射错误');
 const counts={id:c.id};
 for(const type of ['reading','listening']){
  const p=c[type];const n=p.text.trim().split(/\s+/).length;const min=type==='reading'?60:45,max=type==='reading'?90:75;
  if(n<min||n>max)throw Error('测评篇幅 '+c.id+type+n);
  if(passages.has(p.text)||JSON.stringify(source).includes(p.text)||chapters.some(ch=>ch.transfer.some(t=>t.text===p.text)))throw Error('测评篇章重复');
  passages.add(p.text);counts[type+'Words']=n;
  if(p.questions.length!==4)throw Error('阶段题数错误');
  for(const q of p.questions)if(q.options.length!==3||!Number.isInteger(q.answer)||q.answer<0||q.answer>2||!q.explanation)throw Error('阶段题目结构错误');
 }passageCounts.push(counts);
}
fs.writeFileSync(path.join(__dirname,'pt-PT-detail.json'),JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({chapters:chapters.length,transfer:count,grammarCheck:chapters.length*3,originalLessonDuplicates:0,transferInternalDuplicates:0,vocabularyNotes:chapters.length*3,pronunciationExamples:chapters.length*2,checkpoints:checkpoints.length,checkpointQuestions:32,independentPassages:passages.size,passageCounts}));
